"""Local FastMCP mock for the inspector e2e agent (port 8765)."""

from mcp.server.fastmcp import FastMCP
from starlette.requests import Request
from starlette.responses import PlainTextResponse

HOST = "127.0.0.1"
PORT = 8765

mcp = FastMCP(name="inspector-e2e-mock")


@mcp.custom_route("/health", methods=["GET"])  # type: ignore[misc]
async def health(_request: Request) -> PlainTextResponse:
    return PlainTextResponse("ok", status_code=200)


@mcp.tool(name="resolve-library-id")
def resolve_library_id(libraryName: str, query: str = "") -> str:
    return f"mock-resolve-library-id:/mock/{libraryName}"


@mcp.tool(name="get-library-docs")
def get_library_docs(libraryName: str, topic: str = "", tokens: int = 5000) -> str:
    return f"mock-get-library-docs:{libraryName}:{topic}"


@mcp.tool(name="ask_question")
def ask_question(repoName: str, question: str) -> str:
    return f"mock-ask_question:{repoName}:{question}"


@mcp.tool(name="read_wiki_structure")
def read_wiki_structure(repoName: str) -> str:
    return f"mock-read_wiki_structure:{repoName}"


@mcp.tool(name="read_wiki_contents")
def read_wiki_contents(repoName: str, page: str = "") -> str:
    return f"mock-read_wiki_contents:{repoName}:{page}"


if __name__ == "__main__":
    mcp.settings.host = HOST
    mcp.settings.port = PORT
    mcp.run(transport="streamable-http")
